@file:Suppress("NOTHING_TO_INLINE")package mrpapermoon.whisper.toolsimport com.google.android.gms.tasks.Taskimport io.github.oshai.kotlinlogging.KLoggerimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.suspendCancellableCoroutineimport kotlin.coroutines.resumeimport kotlin.coroutines.resumeWithExceptionsuspend inline fun Task<Void>.awaitResult(	tag: String,	vararg payload: Any,	logger: KLogger = KotlinLogging.logger {},) {	suspendCancellableCoroutine { continuation ->		logResult(tag, payload, logger = logger)		addOnCompleteListener { task ->			when {				task.isCanceled -> continuation.cancel()				task.exception != null -> continuation.resumeWithException(task.exception!!)				task.isSuccessful -> continuation.resume(Unit)			}		}	}}inline fun Task<Void>.logResult(	tag: String,	vararg payload: Any,	logger: KLogger = KotlinLogging.logger {},) {	val stringPayload = lazy { payload.joinToString(", ") }	addOnSuccessListener {		logger.debug { "$tag on success | ${stringPayload.value}" }	}	addOnFailureListener {		logger.error(it) { "$tag on failure" }	}	addOnCanceledListener {		logger.debug { "$tag on cancel | ${stringPayload.value}" }	}	addOnCompleteListener {		logger.info { "$tag on complete" }	}	logger.debug { "on call $tag | ${stringPayload.value}" }}